// migrate.js
// A simple database migration script that reads SQL files from ./migrations/
// and logs each filename it would apply, in order.

const fs = require('fs');
const path = require('path');

// Directory where migration files are stored
const migrationsDir = './migrations';

// Read all files in the migrations directory
fs.readdir(migrationsDir, (err, files) => {
    if (err) {
        console.error('Error reading migrations directory:', err);
        process.exit(1);
    }

    // Filter out non-SQL files and sort them
    const sqlFiles = files
        .filter(file => file.endsWith('.sql'))
        .sort(); // Sort alphabetically (or use a more sophisticated sorting method)

    if (sqlFiles.length === 0) {
        console.log('No SQL migration files found.');
        process.exit(0);
    }

    // Log each migration file that would be applied
    console.log('Migrations to apply:');
    sqlFiles.forEach((file, index) => {
        console.log(`${index + 1}. ${file}`);
    });
});

