function postAuditData(auditData) {
    const postData = JSON.stringify(auditData);

    const options = {
        hostname: 'localhost',
        port: 3003,
        path: '/api/audit',
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
            'Content-Length': Buffer.byteLength(postData)
        }
    };

    const req = https.request(options, (res) => {
        console.log(`Audit service response status: ${res.statusCode}`);
        res.on('data', (chunk) => {
            console.log(`Audit service response: ${chunk}`);
        });
    });

    req.on('error', (error) => {
        console.error('Error posting audit data:', error);
    });

    req.write(postData);
    req.end();
}

