/**
 * Database Migration Script
 * 
 * This script reads SQL files from the ./migrations/ directory and logs each filename
 * it would apply, in order. The filenames are expected to be prefixed with a timestamp
 * (e.g., 20230101000000_create_users_table.sql) to determine the order.
 */

const fs = require('fs');
const path = require('path');

// Directory containing migration files
const MIGRATIONS_DIR = './migrations';

// Function to read and list migration files in order
function listMigrations() {
    try {
        // Read all files in the migrations directory
        const files = fs.readdirSync(MIGRATIONS_DIR);

        // Filter for .sql files and sort them based on their timestamp prefix
        const migrationFiles = files
            .filter(file => file.endsWith('.sql'))
            .sort((a, b) => {
                // Extract the timestamp from the filename (assuming format: YYYYMMDDHHMMSS_description.sql)
                const timestampA = a.split('_')[0];
                const timestampB = b.split('_')[0];
                return timestampA.localeCompare(timestampB);
            });

        // Log each migration file in order
        console.log('Migrations to apply (in order):');
        migrationFiles.forEach((file, index) => {
            console.log(`${index + 1}. ${file}`);
        });

        return migrationFiles;
    } catch (error) {
        console.error('Error reading migration files:', error.message);
        return [];
    }
}

// Execute the function
listMigrations();

