const fs = require('fs');
const path = require('path');

// Directory containing migration SQL files
const migrationsDir = path.join(__dirname, './migrations');

// Function to read migration files and log their names
function readAndLogMigrations() {
    // Check if the migrations directory exists
    if (!fs.existsSync(migrationsDir)) {
        console.log(`Migrations directory '${migrationsDir}' does not exist.`);
        return;
    }

    // Read the contents of the migrations directory
    fs.readdir(migrationsDir, (err, files) => {
        if (err) {
            console.error('Error reading migrations directory:', err);
            return;
        }

        // Filter out only .sql files and sort them lexicographically
        const sqlFiles = files
            .filter(file => file.endsWith('.sql'))
            .sort();

        // Log each migration file in order
        if (sqlFiles.length === 0) {
            console.log('No migration files found in the ./migrations/ directory.');
        } else {
            console.log('Migration files to apply (in order):');
            sqlFiles.forEach((file, index) => {
                console.log(`${index + 1}. ${file}`);
            });
        }
    });
}

// Execute the function
readAndLogMigrations();

