// Function to resolve the connection string from .env.test
function resolveConnectionString() {
    const envPath = path.join(__dirname, '.env.test');

    // Check if the .env.test file exists
    if (!fs.existsSync(envPath)) {
        console.log('.env.test file not found. Using default DATABASE_URL.');
        return 'default_database_url';
    }

    // Read the .env.test file
    const envContent = fs.readFileSync(envPath, 'utf8');
    const lines = envContent.split('\n');
    let databaseUrl = 'default_database_url';

    // Parse the DATABASE_URL from the file
    lines.forEach(line => {
        const match = line.match(/^DATABASE_URL=(.*)$/);
        if (match) {
            databaseUrl = match[1];
        }
    });

    return databaseUrl;
}

