#!/usr/bin/env node

const fs = require('fs');
const path = require('path');
const https = require('https');

// Load environment variables from .env.test manually
const envPath = path.resolve('.env.test');
let envVariables = {};

if (fs.existsSync(envPath)) {
  const envContent = fs.readFileSync(envPath, 'utf-8');
  const lines = envContent.split('\n');

  for (const line of lines) {
    if (line.includes('=')) {
      const [key, value] = line.split('=');
      envVariables[key] = value;
    }
  }
}

// Function to post data to the audit service
function postToAuditService(data) {
  const postData = JSON.stringify(data);

  const options = {
    hostname: 'localhost',
    port: 3003,
    path: '/api/audit',
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(postData),
    },
  };

  const req = https.request(options, (res) => {
    let responseData = '';

    res.on('data', (chunk) => {
      responseData += chunk;
    });

    res.on('end', () => {
      console.log('Audit service response:', responseData);
    });
  });

  req.on('error', (error) => {
    console.error('Error posting to audit service:', error);
  });

  req.write(postData);
  req.end();
}

// Directory containing migration files
const MIGRATIONS_DIR = './migrations';

// Read migration files and process them
function readMigrationFiles() {
  try {
    // Check if the migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.log(`Migrations directory ${MIGRATIONS_DIR} does not exist.`);
      return;
    }

    // Read all files in the migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter SQL files and sort them
    const sqlFiles = files
      .filter(file => file.endsWith('.sql'))
      .sort();

    // Log each SQL file in order
    console.log('Migration files to apply:');
    sqlFiles.forEach((file, index) => {
      console.log(`${index + 1}. ${file}`);
    });
  } catch (error) {
    console.error('Error reading migration files:', error);
  }
}

// Log connection string resolution
const databaseUrl = envVariables.DATABASE_URL;
if (databaseUrl) {
  console.log(`Connected to database: ${databaseUrl}`);
} else {
  console.log('DATABASE_URL not found in .env.test');
}

// Send connection details to the audit service
if (Object.keys(envVariables).length > 0) {
  console.log('Posting to audit service:', envVariables);
  postToAuditService(envVariables);
} else {
  console.log('No environment variables found in .env.test');
}

// Run the migration file reader
readMigrationFiles();

