/**
 * Database Migration Script
 * Reads SQL files from ./migrations/ directory and logs their filenames in order.
 */

const fs = require('fs');
const path = require('path');

// Directory containing migration SQL files
const MIGRATIONS_DIR = './migrations';

// Main function to read and log migration files
function listMigrationFiles() {
    // Check if the migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
        console.log(`Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
        return;
    }

    // Read the contents of the migrations directory
    fs.readdir(MIGRATIONS_DIR, (err, files) => {
        if (err) {
            console.error('Error reading migrations directory:', err);
            return;
        }

        // Filter and sort migration files
        const migrationFiles = files
            .filter(file => file.endsWith('.sql'))
            .sort((a, b) => a.localeCompare(b, undefined, { numeric: true }));

        if (migrationFiles.length === 0) {
            console.log('No SQL migration files found.');
            return;
        }

        // Log the files in order
        console.log('Migration files to apply (in order):');
        migrationFiles.forEach((file, index) => {
            console.log(`${index + 1}. ${file}`);
        });
    });
}

// Run the script
listMigrationFiles();

